// resolveO2OJoins inspects FieldOptions and returns JOIN descriptors for each O2O relationship.
// Returns nil if no O2O relationships are requested.
func (c *authorProfileClient) resolveO2OJoins(d sql.Dialect, fo *AuthorProfileFieldOptions) []sql.JoinClause {
	if fo == nil {
		return nil
	}
	var joins []sql.JoinClause
	if fo.Authors != nil {
		joins = append(joins, sql.JoinClause{
			Table: sql.Table{Schema: "", Name: "authors"},
			Alias: "a2",
			On:    fmt.Sprintf("a2.%s = a.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("author_id")),
			// The NULL-detection below reads the target's PK off the scanned
			// row, so the join carries it even when FieldOptions did not ask
			// for it — an unselected PK reads as a LEFT JOIN miss.
			Columns: unionColumns(fo.Authors.Columns(), "id"),
			SoftDelete: &sql.SoftDeleteOptions{
				Column: "deleted_at",
				Type:   sql.SoftDeleteTimestamp,
			},
		})
		if fo.Authors.Profile != nil {
			joins = append(joins, sql.JoinClause{
				Table: sql.Table{Schema: "", Name: "author_profiles"},
				Alias: "p",
				On:    fmt.Sprintf("p.%s = a2.%s", d.QuoteIdentifier("author_id"), d.QuoteIdentifier("id")),
				// The NULL-detection below reads the target's PK off the scanned
				// row, so the join carries it even when FieldOptions did not ask
				// for it — an unselected PK reads as a LEFT JOIN miss.
				Columns: unionColumns(fo.Authors.Profile.Columns(), "id"),
			})
			if fo.Authors.Profile.Authors != nil {
				joins = append(joins, sql.JoinClause{
					Table: sql.Table{Schema: "", Name: "authors"},
					Alias: "a3",
					On:    fmt.Sprintf("a3.%s = p.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("author_id")),
					// The NULL-detection below reads the target's PK off the scanned
					// row, so the join carries it even when FieldOptions did not ask
					// for it — an unselected PK reads as a LEFT JOIN miss.
					Columns: unionColumns(fo.Authors.Profile.Authors.Columns(), "id"),
					SoftDelete: &sql.SoftDeleteOptions{
						Column: "deleted_at",
						Type:   sql.SoftDeleteTimestamp,
					},
				})
				if fo.Authors.Profile.Authors.Profile != nil {
					joins = append(joins, sql.JoinClause{
						Table: sql.Table{Schema: "", Name: "author_profiles"},
						Alias: "p2",
						On:    fmt.Sprintf("p2.%s = a3.%s", d.QuoteIdentifier("author_id"), d.QuoteIdentifier("id")),
						// The NULL-detection below reads the target's PK off the scanned
						// row, so the join carries it even when FieldOptions did not ask
						// for it — an unselected PK reads as a LEFT JOIN miss.
						Columns: unionColumns(fo.Authors.Profile.Authors.Profile.Columns(), "id"),
					})
					if fo.Authors.Profile.Authors.Profile.Authors != nil {
						joins = append(joins, sql.JoinClause{
							Table: sql.Table{Schema: "", Name: "authors"},
							Alias: "a4",
							On:    fmt.Sprintf("a4.%s = p2.%s", d.QuoteIdentifier("id"), d.QuoteIdentifier("author_id")),
							// The NULL-detection below reads the target's PK off the scanned
							// row, so the join carries it even when FieldOptions did not ask
							// for it — an unselected PK reads as a LEFT JOIN miss.
							Columns: unionColumns(fo.Authors.Profile.Authors.Profile.Authors.Columns(), "id"),
							SoftDelete: &sql.SoftDeleteOptions{
								Column: "deleted_at",
								Type:   sql.SoftDeleteTimestamp,
							},
						})
						if fo.Authors.Profile.Authors.Profile.Authors.Profile != nil {
							joins = append(joins, sql.JoinClause{
								Table: sql.Table{Schema: "", Name: "author_profiles"},
								Alias: "p3",
								On:    fmt.Sprintf("p3.%s = a4.%s", d.QuoteIdentifier("author_id"), d.QuoteIdentifier("id")),
								// The NULL-detection below reads the target's PK off the scanned
								// row, so the join carries it even when FieldOptions did not ask
								// for it — an unselected PK reads as a LEFT JOIN miss.
								Columns: unionColumns(fo.Authors.Profile.Authors.Profile.Authors.Profile.Columns(), "id"),
							})
						}
					}
				}
			}
		}
	}
	return joins
}

// scanAuthorProfilesWithOneToOneJoins scans rows from a LEFT JOIN query into
// AuthorProfile entities with O2O relationships populated.
// Routes columns by alias prefix and detects LEFT JOIN misses via NULL PK detection.
func scanAuthorProfilesWithOneToOneJoins(rows database.Rows, columns []string) ([]*AuthorProfile, error) {
	var result []*AuthorProfile
	for rows.Next() {
		a := &AuthorProfile{}
		a2 := &Author{}
		a2HasData := false
		a3 := &Author{}
		a3HasData := false
		a4 := &Author{}
		a4HasData := false
		p := &AuthorProfile{}
		pHasData := false
		p2 := &AuthorProfile{}
		p2HasData := false
		p3 := &AuthorProfile{}
		p3HasData := false

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "a.id":
				targets[idx] = &a.ID
			case "a.author_id":
				targets[idx] = &a.AuthorID
			case "a.bio":
				targets[idx] = &a.Bio
			case "a2.id":
				targets[idx] = database.NullScan(&a2.ID)
				a2HasData = true
			case "a2.name":
				targets[idx] = database.NullScan(&a2.Name)
			case "a2.deleted_at":
				targets[idx] = &a2.DeletedAt
			case "a3.id":
				targets[idx] = database.NullScan(&a3.ID)
				a3HasData = true
			case "a3.name":
				targets[idx] = database.NullScan(&a3.Name)
			case "a3.deleted_at":
				targets[idx] = &a3.DeletedAt
			case "a4.id":
				targets[idx] = database.NullScan(&a4.ID)
				a4HasData = true
			case "a4.name":
				targets[idx] = database.NullScan(&a4.Name)
			case "a4.deleted_at":
				targets[idx] = &a4.DeletedAt
			case "p.id":
				targets[idx] = database.NullScan(&p.ID)
				pHasData = true
			case "p.author_id":
				targets[idx] = &p.AuthorID
			case "p.bio":
				targets[idx] = database.NullScan(&p.Bio)
			case "p2.id":
				targets[idx] = database.NullScan(&p2.ID)
				p2HasData = true
			case "p2.author_id":
				targets[idx] = &p2.AuthorID
			case "p2.bio":
				targets[idx] = database.NullScan(&p2.Bio)
			case "p3.id":
				targets[idx] = database.NullScan(&p3.ID)
				p3HasData = true
			case "p3.author_id":
				targets[idx] = &p3.AuthorID
			case "p3.bio":
				targets[idx] = database.NullScan(&p3.Bio)
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan author_profile with joins: %w", err)
		}

		// NULL detection — assign deepest chain first, then parents
		if p3HasData && p3.ID != 0 {
			a4.Profile = p3
		} else {
			a4.Profile = nil
		}
		if p2HasData && p2.ID != 0 {
			a3.Profile = p2
		} else {
			a3.Profile = nil
		}
		if pHasData && p.ID != 0 {
			a2.Profile = p
		} else {
			a2.Profile = nil
		}
		if a4HasData && a4.ID != 0 {
			p2.Authors = a4
		} else {
			p2.Authors = nil
		}
		if a3HasData && a3.ID != 0 {
			p.Authors = a3
		} else {
			p.Authors = nil
		}
		if a2HasData && a2.ID != 0 {
			a.Authors = a2
		} else {
			a.Authors = nil
		}

		result = append(result, a)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate author_profile rows: %w", err)
	}
	return result, nil
}

