// Paginate returns a page of author_tags with total count for offset-based pagination.
// A nil filter paginates all author_tags.
func (c *authorTagClient) Paginate(ctx context.Context, input PaginateInput[AuthorTagFilter], opts ...func(*CallOptions[AuthorTagFieldOptions])) (*PaginateResult[AuthorTag], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("paginate author_tags: LockMode requires an active transaction")
		}
		options.SkipCache = true
		if options.LockMode == sql.LockForUpdateNoWait || options.LockMode == sql.LockForUpdateSkipLocked {
			version, err := c.mysqlVersion.get(ctx)
			if err != nil {
				return nil, fmt.Errorf("paginate author_tags: %w", err)
			}
			if version.Major < 8 {
				return nil, fmt.Errorf("paginate author_tags: LockMode %s requires MySQL 8.0+ (server reports %s)", options.LockMode, version.Raw)
			}
		}
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableAuthorTags, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[AuthorTagFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate author_tags count: %w", err)
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		authorTags, err := c.GetMany(ctx, &GetAuthorTagsInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate author_tags: %w", err)
		}

		return &PaginateResult[AuthorTag]{
			Items:      authorTags,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    input.Limit > 0 && int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*PaginateResult[AuthorTag]), nil
}

// Connection returns a Relay-style cursor-paginated connection of author_tags.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *authorTagClient) Connection(ctx context.Context, input ConnectionInput[AuthorTagFilter], opts ...func(*CallOptions[AuthorTagFieldOptions])) (*Connection[AuthorTag], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection author_tags: LockMode requires an active transaction")
		}
		options.SkipCache = true
		if options.LockMode == sql.LockForUpdateNoWait || options.LockMode == sql.LockForUpdateSkipLocked {
			version, err := c.mysqlVersion.get(ctx)
			if err != nil {
				return nil, fmt.Errorf("connection author_tags: %w", err)
			}
			if version.Major < 8 {
				return nil, fmt.Errorf("connection author_tags: LockMode %s requires MySQL 8.0+ (server reports %s)", options.LockMode, version.Raw)
			}
		}
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableAuthorTags, Schema: "",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[AuthorTagFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection author_tags count: %w", err)
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeAuthorTagCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeAuthorTagCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		authorTags, err := c.GetMany(ctx, &GetAuthorTagsInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection author_tags: %w", err)
		}

		// Trim extra row and determine page boundaries
		hasMore := len(authorTags) > limit
		if hasMore {
			authorTags = authorTags[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(authorTags)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[AuthorTag], len(authorTags))
		for i, row := range authorTags {
			cursor, err := encodeAuthorTagCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[AuthorTag]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[AuthorTag]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*Connection[AuthorTag]), nil
}

// encodeAuthorTagCursor encodes cursor key values as a base64 JSON string.
func encodeAuthorTagCursor(keys []string, a *AuthorTag) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "author_id":
			out["author_id"] = a.AuthorID
		case "tag_id":
			out["tag_id"] = a.TagID
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode author_tag cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeAuthorTagCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeAuthorTagCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row AuthorTag
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "author_id":
			err = json.Unmarshal(raw[key], &row.AuthorID)
			out[key] = row.AuthorID
		case "tag_id":
			err = json.Unmarshal(raw[key], &row.TagID)
			out[key] = row.TagID
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

