// AuthorClient provides type-safe operations for the authors table.
type AuthorClient interface {
	// --- Read Operations ---

	// Get returns a single author by primary key.
	// Soft-deleted authors are excluded by default (exclude_deleted is enabled).
	// Use GetMany with Filter.DeletedAt comparator to retrieve soft-deleted authors.
	Get(ctx context.Context, id int64, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// GetMany returns authors matching the given filter, field selection, and sort criteria.
	// Soft-deleted authors are excluded by default. Set Filter.DeletedAt to override.
	// When FieldOptions includes O2M or M2M relationships, they are loaded via an
	// errgroup fan-out — in parallel over the pool, and serialized by the
	// transaction's connection reservation when ctx carries one.
	GetMany(ctx context.Context, input *GetAuthorsInput, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// Exists returns true if a author with the given primary key exists.
	// Soft-deleted authors are excluded — a soft-deleted author returns false.
	Exists(ctx context.Context, id int64, opts ...func(*CallOptions[AuthorFieldOptions])) (bool, error)

	// ExistsWhere returns true if any author matches the given filter.
	// Soft-deleted authors are excluded by default.
	ExistsWhere(ctx context.Context, filter *AuthorFilter, opts ...func(*CallOptions[AuthorFieldOptions])) (bool, error)

	// Count returns the number of authors matching the given filter.
	// Soft-deleted authors are excluded by default. A nil filter counts all non-deleted authors.
	Count(ctx context.Context, filter *AuthorFilter, opts ...func(*CallOptions[AuthorFieldOptions])) (int64, error)

	// --- Write Operations ---

	// Create inserts a new author and returns the created entity.
	Create(ctx context.Context, input *CreateAuthorInput, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// CreateMany inserts multiple authors in batches and returns all created entities.
	// Sub-batches are not automatically rolled back on failure — wrap in a transaction for atomicity.
	CreateMany(ctx context.Context, inputs []*CreateAuthorInput, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// Update partially updates a author by primary key and returns the updated entity.
	// Only fields where IsSet() is true are included in the SET clause.
	// Returns ErrNotFound if the primary key does not exist.
	Update(ctx context.Context, id int64, input *UpdateAuthorInput, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// UpdateMany updates multiple authors and returns the updated entities.
	UpdateMany(ctx context.Context, items []UpdateAuthorItem, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// UpdateWhere updates all authors matching the filter and returns the updated entities.
	// Idempotent — returns empty slice when no rows match.
	UpdateWhere(ctx context.Context, filter *AuthorFilter, input *UpdateAuthorInput, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// Upsert inserts a author or updates it on conflict and returns the resulting entity.
	Upsert(ctx context.Context, input *CreateAuthorInput, target AuthorConflictTarget, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// UpsertMany inserts or updates multiple authors in batches and returns all resulting entities.
	// Inputs resolving to the same conflict target are deduped, last occurrence wins.
	UpsertMany(ctx context.Context, inputs []*CreateAuthorInput, target AuthorConflictTarget, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// CreateWithRelated creates a author together with rows on its nested
	// relationships, in a single transaction. Nested rows are written through
	// the target table's own client, so their hooks, events, cache
	// invalidation and tenancy behave exactly as on a direct call.
	CreateWithRelated(ctx context.Context, input *CreateAuthorWithRelatedInput, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// UpdateWithRelated updates a author together with rows on its nested
	// relationships, in a single transaction. The nested blocks add `disconnect`
	// and `clear` to the create-side verbs, because the parent already exists
	// and there are rows to unlink.
	UpdateWithRelated(ctx context.Context, id int64, input *UpdateAuthorWithRelatedInput, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// UpsertWithRelated inserts or updates a author together with rows on
	// its nested relationships, in a single transaction. It reuses the
	// update-side nested block verbatim — each verb means the same thing on
	// either branch, so one block is correct on both. `create` is not
	// idempotent: repeating an upsert that carries it inserts again.
	UpsertWithRelated(ctx context.Context, input *UpsertAuthorWithRelatedInput, target AuthorConflictTarget, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// --- Soft Delete Operations ---

	// SoftDelete marks a author as deleted by setting the deleted_at column and returns
	// the updated entity. Idempotent — returns nil, nil if the primary key does not exist.
	SoftDelete(ctx context.Context, id int64, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// SoftDeleteMany marks multiple authors as deleted and returns the updated entities.
	SoftDeleteMany(ctx context.Context, ids []int64, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// SoftDeleteWhere marks all authors matching the filter as deleted and returns them.
	// Idempotent — returns empty slice when no rows match.
	SoftDeleteWhere(ctx context.Context, filter *AuthorFilter, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// --- Restore Operations ---

	// Restore clears the deleted_at column, restoring a soft-deleted author, and returns it.
	// Idempotent — returns nil, nil if the primary key does not exist.
	Restore(ctx context.Context, id int64, opts ...func(*CallOptions[AuthorFieldOptions])) (*Author, error)

	// RestoreMany restores multiple soft-deleted authors and returns them.
	RestoreMany(ctx context.Context, ids []int64, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// RestoreWhere restores all soft-deleted authors matching the filter and returns them.
	// Idempotent — returns empty slice when no rows match.
	RestoreWhere(ctx context.Context, filter *AuthorFilter, opts ...func(*CallOptions[AuthorFieldOptions])) ([]*Author, error)

	// --- Hard Delete Operations ---

	// HardDelete permanently removes a author from the database.
	// Idempotent — returns nil if the primary key does not exist.
	HardDelete(ctx context.Context, id int64, opts ...func(*CallOptions[AuthorFieldOptions])) error

	// HardDeleteMany permanently removes multiple authors from the database.
	HardDeleteMany(ctx context.Context, ids []int64, opts ...func(*CallOptions[AuthorFieldOptions])) error

	// HardDeleteWhere permanently removes all authors matching the filter.
	// Idempotent — returns nil when no rows match.
	HardDeleteWhere(ctx context.Context, filter *AuthorFilter, opts ...func(*CallOptions[AuthorFieldOptions])) error

	// --- Pagination Operations ---

	// Paginate returns a page of authors with total count for offset-based pagination.
	// Soft-deleted authors are excluded by default.
	Paginate(ctx context.Context, input PaginateInput[AuthorFilter], opts ...func(*CallOptions[AuthorFieldOptions])) (*PaginateResult[Author], error)

	// Connection returns a Relay-style cursor-paginated connection of authors.
	// Sort order is determined by cursor_keys — custom sorts are not supported.
	// Use Paginate for custom sort orders.
	Connection(ctx context.Context, input ConnectionInput[AuthorFilter], opts ...func(*CallOptions[AuthorFieldOptions])) (*Connection[Author], error)

	// Stream returns an iterator over authors matching the filter and sort criteria.
	// Rows are yielded as the driver returns them; cache is bypassed.
	// Stream cannot load relationships.
	//
	// Stream refuses an active transaction unless CallOptions.AllowInTransaction
	// is set, and the opt-in commits the caller to issuing nothing else on that
	// txCtx: the one rule that remains the caller's — drain or close a result set
	// before issuing the next statement on that txCtx — applied to a loop whose
	// body is caller code.
	Stream(ctx context.Context, input *StreamAuthorsInput, opts ...func(*CallOptions[StreamAuthorFieldOptions])) iter.Seq2[*Author, error]
}

